import{_ as a,c as n,o as e,V as p}from"./chunks/framework.e2d10ea7.js";const s="/ocean-of-knowledge/assets/image.5baf8654.png",l="/ocean-of-knowledge/assets/image-1.83f539c4.png",f=JSON.parse('{"title":"pnpm 的使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-module/node/pnpm/index.md","filePath":"knowledge-module/node/pnpm/index.md"}'),t={name:"knowledge-module/node/pnpm/index.md"},o=p('<h1 id="pnpm-的使用教程" tabindex="-1">pnpm 的使用教程 <a class="header-anchor" href="#pnpm-的使用教程" aria-label="Permalink to &quot;pnpm 的使用教程&quot;">​</a></h1><h2 id="官网教程" tabindex="-1">官网教程 <a class="header-anchor" href="#官网教程" aria-label="Permalink to &quot;官网教程&quot;">​</a></h2><p><a href="https://pnpm.io/zh/" target="_blank" rel="noreferrer">官网地址：https://pnpm.io/zh/</a></p><h2 id="使用-pnpm-的目的-——-节省磁盘空间" tabindex="-1">使用 pnpm 的目的 —— 节省磁盘空间 <a class="header-anchor" href="#使用-pnpm-的目的-——-节省磁盘空间" aria-label="Permalink to &quot;使用 pnpm 的目的 —— 节省磁盘空间&quot;">​</a></h2><p><img src="'+s+`" alt="Alt text"></p><ul><li><p>使用 npm 时，依赖每次被不同的项目使用，都会重复安装一次。</p></li><li><p>而在使用 pnpm 时，依赖会被存储在内容可寻址的存储中， 所以：</p></li></ul><p>如果你用到了某依赖项的不同版本，只会将不同版本间有差异的文件添加到仓库。 例如，如果某个包有 100 个文件，而它的新版本只改变了其中 1 个文件。那么 pnpm update 时只会向存储中心额外添加 1 个新文件，而不会因为仅仅一个文件的改变复制整新版本包的内容。</p><p>所有文件都会存储在硬盘上的某一位置。 当软件包被被安装时，包里的文件会硬链接到这一位置，而不会占用额外的磁盘空间。 这允许你跨项目地共享同一版本的依赖。</p><ul><li>因此，您在磁盘上节省了大量空间，这与项目和依赖项的数量成正比，并且安装速度要快得多！</li></ul><h2 id="安装-pnpm" tabindex="-1">安装 pnpm <a class="header-anchor" href="#安装-pnpm" aria-label="Permalink to &quot;安装 pnpm&quot;">​</a></h2><ul><li><p>前端使用 node 安装时， node 的版本最低需要支持 16.X 版本</p></li><li><p>npm 安装</p></li></ul><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">npm install pnpm </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;">g</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 或</span></span>
<span class="line"><span style="color:#A6ACCD;">npm install </span><span style="color:#89DDFF;">@</span><span style="color:#A6ACCD;">pnpm</span><span style="color:#89DDFF;">/</span><span style="color:#A6ACCD;">exe </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;">g</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="功能对比" tabindex="-1">功能对比 <a class="header-anchor" href="#功能对比" aria-label="Permalink to &quot;功能对比&quot;">​</a></h2><p><img src="`+l+'" alt="Alt text"></p><h2 id="pnpm-的命令" tabindex="-1">pnpm 的命令 <a class="header-anchor" href="#pnpm-的命令" aria-label="Permalink to &quot;pnpm 的命令&quot;">​</a></h2><p><a href="https://pnpm.nodejs.cn/" target="_blank" rel="noreferrer">pnpm 的具体操作指令看这里</a></p>',16),r=[o];function i(c,m,d,h,u,_){return e(),n("div",null,r)}const g=a(t,[["render",i]]);export{f as __pageData,g as default};
